AddCSLuaFile("shared.lua"); AddCSLuaFile("cl_init.lua"); include("shared.lua")
util.AddNetworkString("GRM_CitadelTerminal_Open"); util.AddNetworkString("GRM_CitadelTerminal_Action")
function ENT:Initialize() self:SetModel("models/props_combine/combine_interface001.mdl"); self:PhysicsInit(SOLID_VPHYSICS); self:SetMoveType(MOVETYPE_VPHYSICS); self:SetSolid(SOLID_VPHYSICS); self:SetUseType(SIMPLE_USE); local p=self:GetPhysicsObject(); if IsValid(p) then p:EnableMotion(false) end; self:LinkNearest() end
function ENT:LinkNearest() local best; for _,e in ipairs(ents.FindByClass("grm_citadel_core")) do local d=self:GetPos():DistToSqr(e:GetPos()); if d<100000 and (not best or d<best.d) then best={e=e,d=d} end end; self:SetCore(best and best.e or NULL) end
function ENT:Use(p) self:LinkNearest(); net.Start("GRM_CitadelTerminal_Open"); net.WriteEntity(self); net.WriteEntity(self:GetCore()); net.Send(p) end
net.Receive("GRM_CitadelTerminal_Action",function(_,p) local t=net.ReadEntity(); local a=net.ReadString(); if not IsValid(t) or t:GetClass()~="grm_citadel_core_terminal" or p:GetPos():DistToSqr(t:GetPos())>62500 or not p:IsSuperAdmin() then return end; t:LinkNearest(); local c=t:GetCore(); if not IsValid(c) then return end; if a=="install" then c:Install() elseif a=="toggle" and c:GetInstalled() then c:SetActive(not c:GetActive()) elseif a=="cool" then c:SetHeat(math.max(0,c:GetHeat()-25)); c:SetStability(math.min(100,c:GetStability()+10)) elseif a=="fill" then c:AddEnergy(25000) end end)
